import { Object3D, Vector3, Euler } from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [name]
 * @property {string} meshUrl
 * @property {Array<number>} position
 * @property {Array<number>} rotation
 * @property {Array<number>} scale
 * @property {Array<Object>} [cinematicPrimitives]
 * @property {Array<Object>} [textContent]
 * @property {Array<Object>} [behaviors]
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>any} glbLoader
 * @property {any} primitives
 * @property {any} fontAtlas
 * @property {(event:string)=>void} [emit]
 */

/**
 * Creates an ornamental divider node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
    // Root container
    const root = new Object3D();
    if (config.name) root.name = config.name;
    else root.name = 'ornamental-divider';

    // Load GLB (synchronous via ctx.glbLoader)
    const glb = ctx.glbLoader(config.meshUrl);
    const mesh = glb.scene || glb; // handle possible GLTF structure
    root.add(mesh);

    // Apply transforms
    const pos = new Vector3(...config.position);
    const rot = new Euler(...config.rotation);
    const scl = new Vector3(...config.scale);
    root.position.copy(pos);
    root.rotation.copy(rot);
    root.scale.copy(scl);

    // Apply cinematic primitives if any (none expected for this node)
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const primitive of config.cinematicPrimitives) {
            const fn = ctx.primitives?.[primitive.name];
            if (typeof fn === 'function') {
                fn(root, primitive.params);
            }
        }
    }

    // Interaction: hover rise‑in (subtle 0.15 scene units)
    const originalY = root.position.y;
    const hoverTL = gsap.timeline({ paused: true });
    hoverTL.to(root.position, {
        y: originalY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
    });

    // Interaction: click emit event
    const emitEvent = () => {
        if (typeof ctx.emit === 'function') {
            ctx.emit('hub-home.select');
        }
    };

    // Store handlers in userData
    root.userData.handlers = {
        /** @param {'enter'|'leave'} state */
        hover(state) {
            if (state === 'enter') hoverTL.play();
            else if (state === 'leave') hoverTL.reverse();
        },
        click: emitEvent,
    };

    // Data binding placeholder
    root.userData.bindings = [
        { source: 'trpc.visits.book.slot', target: 'confirmPanel' },
    ];

    // Cleanup routine
    root.userData.cleanup = () => {
        hoverTL.kill();
        // Dispose geometries & materials from the loaded mesh
        mesh.traverse((obj) => {
            if (obj.isMesh) {
                if (obj.geometry) obj.geometry.dispose();
                const mat = obj.material;
                if (Array.isArray(mat)) {
                    mat.forEach((m) => m && m.dispose && m.dispose());
                } else if (mat) {
                    mat.dispose();
                }
            }
        });
    };

    return root;
}
